--    python3 -c "import json; print(json.dumps({'query': open('supabase/backups/baseline_2026-07-28.sql').read()}))" > /tmp/restore.json
--    curl -s -X POST "https://api.supabase.com/v1/projects/<project-ref>/database/query" \
--      -H "Authorization: Bearer $SUPABASE_ACCESS_TOKEN" -H "Content-Type: application/json" \
--      -d @/tmp/restore.json
--  Para probar SIN aplicar de verdad: cambia el 'commit;' final por 'rollback;'.
-- =====================================================================

